function topologicalSort(nodeCount, edges) {
  const adj = Array.from({ length: nodeCount }, () => []);
  const inDegree = new Array(nodeCount).fill(0);

  for (const [before, after] of edges) {
    adj[before].push(after);
    inDegree[after]++;                 // one more thing blocking it
  }

  const ready = [];
  for (let v = 0; v < nodeCount; v++) if (inDegree[v] === 0) ready.push(v);

  const order = [];
  while (ready.length > 0) {
    const v = ready.pop();
    order.push(v);
    for (const next of adj[v]) {
      if (--inDegree[next] === 0) ready.push(next);
    }
  }

  // Anything left un-emitted is stuck behind a cycle.
  return order.length === nodeCount ? order : null;
}
